from ortools.sat.python import cp_model
import json

# Input data
jobs_data = [  # (job_id, task_id) -> (machine_id, duration)
    [(0, 3), (1, 2), (2, 2)],  # Job 0
    [(0, 2), (2, 1), (1, 4)],  # Job 1
    [(1, 4), (2, 3)]           # Job 2
]

# Model definition
model = cp_model.CpModel()

# Number of jobs and machines
num_jobs = len(jobs_data)
num_machines = 1 + max(task[0] for job in jobs_data for task in job)

# Decision Variables
# start[job][task] is the start time of task 'task' in job 'job'.
start = {}
duration = {}
end = {}
for job in range(num_jobs):
    for task_id, task in enumerate(jobs_data[job]):
        machine = task[0]
        duration[job, task_id] = task[1]
        start[job, task_id] = model.NewIntVar(0, 1000, f'start[{job},{task_id}]')
        end[job, task_id] = model.NewIntVar(0, 1000, f'end[{job},{task_id}]')
        model.Add(end[job, task_id] == start[job, task_id] + duration[job, task_id])

# Constraints
# No task for a job can be started until the previous task for that job is completed.
for job in range(num_jobs):
    for task_id in range(1, len(jobs_data[job])):
        model.Add(start[job, task_id] >= end[job, task_id - 1])

# A machine can only work on one task at a time.
for machine in range(num_machines):
    intervals = []
    for job in range(num_jobs):
        for task_id, task in enumerate(jobs_data[job]):
            if task[0] == machine:
                intervals.append(
                    model.NewIntervalVar(start[job, task_id], duration[job, task_id], end[job, task_id],
                                         f'interval[{job},{task_id}]'))
    model.AddNoOverlap(intervals)

# Objective function: minimize the makespan
makespan = model.NewIntVar(0, 1000, 'makespan')
model.AddMaxEquality(makespan, [end[job, len(jobs_data[job]) - 1] for job in range(num_jobs)])
model.Minimize(makespan)

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        'makespan': solver.Value(makespan)
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
